"use strict";(self.webpackChunkdev_knowledge_base=self.webpackChunkdev_knowledge_base||[]).push([[8486],{7750:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>i,metadata:()=>s,toc:()=>l});var s=n(64925),o=n(74848),a=n(28453);const i={title:"The Hard Part Of Agents Is Not How Smart The Model Is",authors:"DingZhiyu",tags:["tech"],description:"After reading LangChain's article on Agent Harness, this note looks at why planning, state, permissions, and evaluation outside the model determine whether an Agent can work reliably."},r="The Hard Part Of Agents Is Not How Smart The Model Is",h={authorsImageUrls:[void 0]},l=[];function d(e){const t={a:"a",code:"code",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:"Here is what happened."}),"\n",(0,o.jsxs)(t.p,{children:["On April 7, I spent some time reading LangChain's article, ",(0,o.jsx)(t.a,{href:"https://blog.langchain.com/the-anatomy-of-an-agent-harness/",children:"The Anatomy of an Agent Harness"}),"."]}),"\n",(0,o.jsx)(t.p,{children:'At first, I was drawn in by the word "harness."'}),"\n",(0,o.jsx)(t.p,{children:'It has been appearing more and more often in the Agent world recently, but it is also a slightly awkward word. If you translate it directly as "tack" or "restraint gear," it sounds strange. If you translate it as "framework," it feels too light, as if it is only a few layers of code wrapping. "Exoskeleton" may be a bit closer, but it is still not exact.'}),"\n",(0,o.jsx)(t.p,{children:"In any case, it points to this thing:"}),"\n",(0,o.jsx)(t.p,{children:"the whole system outside the model that lets an Agent actually do work."}),"\n",(0,o.jsx)(t.p,{children:"My strongest feeling after reading it was that, in the past, we may have stared too much at the model itself."}),"\n",(0,o.jsx)(t.p,{children:"Which model is smarter."}),"\n",(0,o.jsx)(t.p,{children:"Which model reasons better."}),"\n",(0,o.jsx)(t.p,{children:"Which model writes code more fiercely."}),"\n",(0,o.jsx)(t.p,{children:"These things are of course important. You cannot take a very weak model and insist that engineering alone can make up for it. That is unrealistic."}),"\n",(0,o.jsx)(t.p,{children:"But if you have really used Claude Code, Codex, Cursor, or built Agents yourself with LangGraph, the OpenAI Agents SDK, or CrewAI, you quickly run into an annoying problem."}),"\n",(0,o.jsx)(t.p,{children:"A smart model does not equal a reliable system."}),"\n",(0,o.jsx)(t.p,{children:"It can think of the next step, but that does not mean it knows when to stop."}),"\n",(0,o.jsx)(t.p,{children:"It can call tools, but that does not mean it knows which tools must not be used carelessly."}),"\n",(0,o.jsx)(t.p,{children:"It can write files, but that does not mean it knows how to roll back a bad change."}),"\n",(0,o.jsx)(t.p,{children:"It can read context, but that does not mean it will not tie itself in knots after a dozen turns."}),"\n",(0,o.jsx)(t.p,{children:"It is like putting a very smart person into a car with no steering wheel, no brakes, and no dashboard."}),"\n",(0,o.jsx)(t.p,{children:"The brain is good."}),"\n",(0,o.jsx)(t.p,{children:"The car is not."}),"\n",(0,o.jsx)(t.p,{children:"What moved me most in the LangChain article was that it made this problem very concrete. It was not vaguely saying that Agents need engineering. It took the harness apart and showed you planning, filesystem, subagents, stateful middleware, context engineering, tool permission, and evaluation loop."}),"\n",(0,o.jsx)(t.p,{children:"None of these words look exciting."}),"\n",(0,o.jsx)(t.p,{children:"But every one of them is critical."}),"\n",(0,o.jsx)(t.p,{children:"Take planning, for example."}),"\n",(0,o.jsx)(t.p,{children:"Many people may think a plan is just asking the model to write a todo list. Sounds ordinary, right?"}),"\n",(0,o.jsx)(t.p,{children:"But think about what most often goes wrong when an Agent does a complex task. It is not that it completely cannot do the work. It is that it drifts while doing it. It starts out fixing a bug, then halfway through begins refactoring the whole project. It starts out writing an article, then halfway through adds a pile of background material barely related to the topic."}),"\n",(0,o.jsx)(t.p,{children:"At that moment, a plan is not decoration."}),"\n",(0,o.jsx)(t.p,{children:"A plan is a rope."}),"\n",(0,o.jsx)(t.p,{children:"It is not there to restrict the model for the sake of restriction. It is there so that every so often the model can look back and see what it is actually doing."}),"\n",(0,o.jsx)(t.p,{children:"The filesystem is the same."}),"\n",(0,o.jsx)(t.p,{children:"We used to think the longer the context window, the better. The longer the window, the more the model remembers, and the stronger the Agent becomes."}),"\n",(0,o.jsx)(t.p,{children:"That is only half true."}),"\n",(0,o.jsx)(t.p,{children:"Long context is useful, but you cannot stuff everything into it. Code repositories, logs, drafts, materials, previous attempts, intermediate results. Once everything goes into the context, the model looks as if it knows everything, but in reality its attention becomes scattered."}),"\n",(0,o.jsx)(t.p,{children:"The filesystem is another brain."}),"\n",(0,o.jsx)(t.p,{children:"Write down what should be remembered. Read it back when it should be read. You do not need to stuff the whole world into the prompt. You only need the model to know where things are, and when to retrieve them."}),"\n",(0,o.jsx)(t.p,{children:"This has also become one of my strongest feelings recently."}),"\n",(0,o.jsx)(t.p,{children:"An Agent is not a model that is better at chatting."}),"\n",(0,o.jsx)(t.p,{children:"An Agent is a model placed into an environment."}),"\n",(0,o.jsx)(t.p,{children:"Once the environment becomes complex, the problem changes."}),"\n",(0,o.jsxs)(t.p,{children:["The early ReAct pattern had already exposed this issue. The model thinks one step, acts, observes, and then continues thinking. Back then it was still a very simple loop of ",(0,o.jsx)(t.code,{children:"Thought"}),", ",(0,o.jsx)(t.code,{children:"Action"}),", and ",(0,o.jsx)(t.code,{children:"Observation"}),", almost like hand-building a small operating loop inside a prompt."]}),"\n",(0,o.jsx)(t.p,{children:"Then AutoGPT had its moment. For the first time, many people saw a model decomposing tasks, searching, writing files, and continuing to iterate by itself. It felt astonishing."}),"\n",(0,o.jsx)(t.p,{children:"And very soon, people saw the other side."}),"\n",(0,o.jsx)(t.p,{children:"It gets lost."}),"\n",(0,o.jsx)(t.p,{children:"It falls into loops."}),"\n",(0,o.jsx)(t.p,{children:"It works very hard in a large circle, and finally hands over something no one knows how to evaluate."}),"\n",(0,o.jsx)(t.p,{children:"That moment already proved that a model's ability to think is not enough. You still have to give it state, permissions, tool boundaries, error recovery, and places where humans can intervene."}),"\n",(0,o.jsx)(t.p,{children:"Back to the harness."}),"\n",(0,o.jsx)(t.p,{children:'I think what LangChain\'s article really wanted to say was not, "We have invented another new concept."'}),"\n",(0,o.jsx)(t.p,{children:"It was more like a reminder that a large part of Agent capability lives outside the model."}),"\n",(0,o.jsx)(t.p,{children:"There was an interesting example in the article. They said that with the model unchanged, changing the harness moved a coding Agent from Top 30 to Top 5 on Terminal Bench 2.0."}),"\n",(0,o.jsx)(t.p,{children:"That result should not be mythologized. A benchmark is always only a slice."}),"\n",(0,o.jsx)(t.p,{children:"But it is enough to make the point."}),"\n",(0,o.jsx)(t.p,{children:"The same model can perform very differently when placed inside different systems."}),"\n",(0,o.jsx)(t.p,{children:"This is actually similar to people."}),"\n",(0,o.jsx)(t.p,{children:"A smart person without schedules, documents, collaboration tools, review mechanisms, or reminders about priority can also become chaotic. Conversely, someone whose ability is not exaggerated can still produce steadily if they have good processes, notes, tools, and feedback systems."}),"\n",(0,o.jsx)(t.p,{children:"Agents are the same."}),"\n",(0,o.jsx)(t.p,{children:"The model is the brain."}),"\n",(0,o.jsx)(t.p,{children:"The harness is the work habit."}),"\n",(0,o.jsx)(t.p,{children:"At this point, I suddenly understood why products like Claude Code are so compelling."}),"\n",(0,o.jsx)(t.p,{children:"It does not only give you a model that writes code better. It gives the model a very concrete work setting. It can read a repo, edit files, run tests, inspect errors, confirm dangerous operations with you, and keep moving through a task."}),"\n",(0,o.jsx)(t.p,{children:"Behind those experiences is the harness."}),"\n",(0,o.jsx)(t.p,{children:"The OpenAI Agents SDK is moving in the same direction. It brings concepts like agent, handoff, guardrail, session, and tracing into the SDK. Anthropic's MCP is, in a sense, trying to standardize the way models connect to external tools. LangGraph feels more like a controllable Agent runtime for developers, so that state, branching, human intervention, and durable execution do not all have to be handmade from scratch."}),"\n",(0,o.jsx)(t.p,{children:"You can see it: everyone says they are talking about Agents."}),"\n",(0,o.jsx)(t.p,{children:"But the real competition increasingly looks like a competition over whose shell is better."}),"\n",(0,o.jsx)(t.p,{children:"This matters to ordinary developers too."}),"\n",(0,o.jsx)(t.p,{children:"If you are only playing around, pick whatever product you like. If Claude Code feels good, use Claude Code. If Cursor suits you, use Cursor. If the OpenAI Agents SDK is convenient, use the OpenAI Agents SDK."}),"\n",(0,o.jsx)(t.p,{children:"But if you really want to put an Agent into your own business, you cannot only ask whether the model is strong."}),"\n",(0,o.jsx)(t.p,{children:"You also have to ask where its memory lives."}),"\n",(0,o.jsx)(t.p,{children:"Who manages tool permissions."}),"\n",(0,o.jsx)(t.p,{children:"How failure recovers."}),"\n",(0,o.jsx)(t.p,{children:"Whether logs can be replayed."}),"\n",(0,o.jsx)(t.p,{children:"Whether humans can step in at critical points."}),"\n",(0,o.jsx)(t.p,{children:"Whether this workflow can be carried over when you change models later."}),"\n",(0,o.jsx)(t.p,{children:"This question will only become more important."}),"\n",(0,o.jsx)(t.p,{children:"Because after using Agents for a long time, the most valuable thing may not be any single answer, but the working style accumulated around it. It knows how you write code, how you organize materials, your team's process, which commands are dangerous, and which files should not be touched."}),"\n",(0,o.jsx)(t.p,{children:"If all of that sinks into a closed-source product, you may feel very comfortable in the short term."}),"\n",(0,o.jsx)(t.p,{children:"In the long term, you may feel uneasy."}),"\n",(0,o.jsx)(t.p,{children:"This is not to say closed-source products are bad."}),"\n",(0,o.jsx)(t.p,{children:"I use them too, and in many cases they are indeed good."}),"\n",(0,o.jsx)(t.p,{children:"But we need to know what we are handing over."}),"\n",(0,o.jsx)(t.p,{children:"We used to say that model vendors sell intelligence. Now it seems that, in the future, they may sell an entire work environment. The longer you work inside it, the more it understands you, and the harder it becomes to leave."}),"\n",(0,o.jsx)(t.p,{children:"Big times, my friends."}),"\n",(0,o.jsx)(t.p,{children:"So my mindset when looking at Agents is no longer quite the same."}),"\n",(0,o.jsx)(t.p,{children:"When I saw a new Agent demo before, I would first ask what model it used."}),"\n",(0,o.jsx)(t.p,{children:"Now I first ask what its harness is."}),"\n",(0,o.jsx)(t.p,{children:"Does it have a planning system?"}),"\n",(0,o.jsx)(t.p,{children:"Does it have external memory?"}),"\n",(0,o.jsx)(t.p,{children:"Does it have tool permissions?"}),"\n",(0,o.jsx)(t.p,{children:"Does it have observability?"}),"\n",(0,o.jsx)(t.p,{children:"Does it have rollback and evaluation?"}),"\n",(0,o.jsx)(t.p,{children:"Is it a smart brain that can chat, or a small system that can truly do work reliably?"}),"\n",(0,o.jsx)(t.p,{children:"That is the difference."}),"\n",(0,o.jsx)(t.p,{children:"After reading the article on April 7, an image kept staying in my mind."}),"\n",(0,o.jsx)(t.p,{children:"A model stands at the center of the stage, and everyone is watching how smart it is."}),"\n",(0,o.jsx)(t.p,{children:"But lighting, sound, teleprompter, backstage coordination, stage machinery, and emergency brakes are all hidden in the dark."}),"\n",(0,o.jsx)(t.p,{children:"The audience sees the actor."}),"\n",(0,o.jsx)(t.p,{children:"What really decides whether the performance can finish smoothly is the whole theater."}),"\n",(0,o.jsx)(t.p,{children:"Agents are the same."}),"\n",(0,o.jsx)(t.p,{children:"We will of course keep chasing stronger models."}),"\n",(0,o.jsx)(t.p,{children:"But perhaps from now on, we also need to look carefully at the theater beneath the model's feet."})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>r});var s=n(96540);const o={},a=s.createContext(o);function i(e){const t=s.useContext(a);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),s.createElement(a.Provider,{value:t},e.children)}},64925:e=>{e.exports=JSON.parse('{"permalink":"/en/blog/2026/04/07/agent-harness","source":"@site/i18n/en/docusaurus-plugin-content-blog/2026-04-07-agent-harness.mdx","title":"The Hard Part Of Agents Is Not How Smart The Model Is","description":"After reading LangChain\'s article on Agent Harness, this note looks at why planning, state, permissions, and evaluation outside the model determine whether an Agent can work reliably.","date":"2026-04-07T00:00:00.000Z","tags":[{"inline":false,"label":"Tech","permalink":"/en/blog/tags/tech"}],"readingTime":7.93,"hasTruncateMarker":true,"authors":[{"name":"DingZhiyu","title":"Southwest Petroleum University","url":"https://nevergpdzy.com","email":"dingzhiyu2004@163.com","socials":{"github":"https://github.com/NeverGpDzy","steam":"https://steamcommunity.com/id/nevergpdzy/"},"imageURL":"https://oss.nevergpdzy.com/img_for_Typora/6cdbc90753f6f68dda6fc8243b6baef.jpg","key":"DingZhiyu","page":null}],"frontMatter":{"title":"The Hard Part Of Agents Is Not How Smart The Model Is","authors":"DingZhiyu","tags":["tech"],"description":"After reading LangChain\'s article on Agent Harness, this note looks at why planning, state, permissions, and evaluation outside the model determine whether an Agent can work reliably."},"unlisted":false,"prevItem":{"title":"Be Brave, Be Strong","permalink":"/en/blog/2026/04/14/be-brave-and-strong"},"nextItem":{"title":"Paper Is Dead, Hardcore Research Must Rise","permalink":"/en/blog/2026/04/02/paper-is-dead-hardcore-research"}}')}}]);